3	import * as vscode from 'vscode';
4	import {
5	  CheckpointIndex,
6	  LIST_LIMIT,
7	  loadPage,
8	  PAGE_SIZE,
9	  type SessionCheckpoint,
10	} from '../core/checkpointIndex';
11	import { CheckpointStore } from '../core/checkpointStore';
12	import {
13	  isExecutableFile,
14	  isSupportedVersion,
15	  locateCli,
16	  loginShellProbe,
17	  MIN_CLI_VERSION_TEXT,
18	  type CliVersion,
19	} from '../core/cliLocator';
20	import { EntireCli } from '../core/entireCli';
21	import { fail, type Failure, type Result } from '../core/errors';
22	import type { Exec } from '../core/exec';
23	import type { Git, RepoPaths } from '../core/git';
24	import {
25	  REMOTE_SESSIONS_PAGE,
26	  type RemoteCheckpoint,
27	  type RemoteSession,
28	  type RemoteSessionPage,
29	} from '../core/remoteSessions';
30	import { Lane } from '../core/scheduler';
31	import type { CheckpointDetail, SessionRow, StatusInfo, TrailDetail, TrailSummary } from '../core/schemas';
32	import { TrailMemory } from '../core/trailMemory';
33	import {
34	  addTrailPage,
35	  DEFAULT_TRAIL_FILTER,
36	  inTrailFilter,
37	  readTrailPages,
38	  trailFilterKey,
39	  trailProject,
40	  trailRepo,
41	  type TrailFilter,
42	  type TrailListStatus,
43	  type TrailPages,
44	  type TrailRef,
45	} from '../core/trails';
46	import { parseEntireRemote, resolveWebBase, type EntireRepo } from '../core/webLinks';
47	
48	/**
49	 * Names of the lists the views page through. Each list shows one page of rows
50	 * and grows by a page when its Load More row is used.
51	 */
52	export const LISTS = {
53	  commits: 'commits',
54	  otherCheckpoints: 'other',
55	  activeSessions: 'sessions:active',
56	  recentSessions: 'sessions:recent',
57	  sessionCheckpoints: (sessionId: string): string => `session:${sessionId}`,
58	  /**
59	   * Each fresh read of the trails, and each change of the filter, gets a list
60	   * of its own, so it starts again at one page and its Load More row is new
61	   * to the editor.
62	   */
63	  trails: (filter: string, read: number): string => `trails:${filter}:${read}`,
64	} as const;
65	
66	export type ViewState = 'loading' | 'noFolder' | 'notGit' | 'cliMissing' | 'cliTooOld' | 'notEnabled' | 'ready';
67	
68	/** What the Trails view shows: rows, or the reason it has none. */
69	export type TrailsState = 'loading' | 'loggedOut' | 'noAccess' | 'failed' | 'empty' | 'ready';
70	
71	/**
72	 * The trails of one repository, as far as they have been read: the ones the
73	 * CLI lists for a status. The view's filter may show only some of them. See
74	 * `RepoManager.shownTrails`.
75	 */
76	export interface TrailList extends TrailPages {
77	  /** The list's name for paging. See `LISTS.trails`. */
78	  list: string;
79	  /** What the CLI was asked to list: open trails, closed trails, or all. */
80	  status: TrailListStatus;
81	  /** The first page is being read. */
82	  loading: boolean;
83	  /** Why the last read failed. */
84	  failure?: Failure;
85	}
86	
87	/**
88	 * Entire's list of a repository's sessions, as far as it has been read. It
89	 * is the list on the Sessions page of entire.com, and it names each session.
90	 */
91	export interface RemoteSessionList {
92	  /** By session ID, in Entire's order: most recent activity first. */
93	  sessions: Map<string, RemoteSession>;
94	  /** Asks Entire for the next page. Absent once the last page has been read. */
95	  nextCursor?: string;
96	  /** The first page is being read. */
97	  loading: boolean;
98	  /** Why the last read failed. */
99	  failure?: Failure;
100	}
101	
102	/** The checkpoints Entire lists for one session. `checkpoints` is set once the read has answered. */
103	interface RemoteCheckpointRead {
104	  read: Promise<RemoteCheckpoint[] | undefined>;
105	  checkpoints?: RemoteCheckpoint[];
106	  /** When the read failed. It is not tried again for a while, or until a manual refresh. */
107	  failedAt?: number;
108	}
109	
110	/**
111	 * How long a failed read of a session's checkpoints stands. The Sessions
112	 * view asks again each time it redraws, which it does every few seconds.
113	 */
114	const REMOTE_CHECKPOINTS_RETRY_MS = 60_000;
115	
116	/** Pages of sessions one read may ask Entire for, so a long list cannot be read to its end in one go. */
117	const MAX_REMOTE_SESSION_PAGES_PER_READ = 4;
118	
119	function addRemoteSessions(list: RemoteSessionList, page: RemoteSessionPage, asked?: string): void {
120	  // A session moves to the front when it sees activity, so it can turn up again on a later page.
121	  for (const session of page.sessions) {
122	    if (!list.sessions.has(session.sessionId)) list.sessions.set(session.sessionId, session);
123	  }
124	  // A cursor that leads back to itself would be asked for without end.
125	  if (page.nextCursor && page.nextCursor !== asked) list.nextCursor = page.nextCursor;
126	  else delete list.nextCursor;
127	}
128	
129	const instant = (date?: string): number => (date ? Date.parse(date) : 0) || 0;
130	
131	const DETAIL_CACHE_SIZE = 200;
132	/**
133	 * A checkpoint is addressed by ID and changes only when the CLI finalizes its
134	 * transcript or adds a summary, so details are reused for this long. A manual
135	 * refresh clears them.
136	 */
137	const DETAIL_TTL_MS = 5 * 60_000;
138	/** Automatic enrichment runs at most this often per repository. */
139	const ENRICHMENT_MIN_INTERVAL_MS = 60_000;
140	const ENRICHMENT_DEBOUNCE_MS = 3000;
141	
142	/** A session as the Sessions view shows it, merged from every source that knows it. */
143	export interface SessionEntry {
144	  sessionId: string;
145	  agent?: string;
146	  model?: string;
147	  /** `active`, `idle`, `ended`, or undefined when only checkpoints mention it. */
148	  status?: string;
149	  branch?: string;
150	  /**
151	   * The session's name. For a session that Entire lists, it is the name
152	   * entire.com shows: one a person set, or else the title Entire wrote. For
153	   * any other, it is the prompt that opened the session, known once the
154	   * transcript of one of its checkpoints has been read.
155	   */
156	  name?: string;
157	  /** The prompt that opened the session, when that is known and is not its name. */
158	  opening?: string;
159	  /** How many checkpoints Entire counts for the session. Set for a session that Entire lists. */
160	  listedCheckpoints?: number;
161	  /** Entire's own list of the session's checkpoints has been read, and `checkpoints` holds it. */
162	  checkpointsFromEntire?: boolean;
163	  /** The latest prompt, known only when local session state exists. */
164	  lastPrompt?: string;
165	  /** Message of the newest checkpoint: its commit subject, or its prompt when no commit carries it. */
166	  title?: string;
167	  /** ISO time of the last activity or the newest checkpoint. */
168	  lastActive?: string;
169	  /** The row from `entire session list`, when local state exists. */
170	  local?: SessionRow;
171	  /** Newest first. */
172	  checkpoints: SessionCheckpoint[];
173	  /** The session may have earlier checkpoints than the ones listed here. */
174	  mayHaveEarlier?: boolean;
175	}
176	
177	export class RepoContext {
178	  readonly name: string;
179	  originUrl?: string;
180	  entireRepo?: EntireRepo;
181	  branch?: string;
182	  status?: StatusInfo;
183	  index?: CheckpointIndex;
184	  /** Set when the commit history could not be read. */
185	  gitError?: string;
186	  sessionRows?: SessionRow[];
187	  /** Bumped whenever the branch tip changes, so late results can be dropped. */
188	  generation = 0;
189	  lastEnrichment = 0;
190	  lastRefresh = 0;
191	  enrichmentTimer?: NodeJS.Timeout;
192	  readonly details = new Map<string, { at: number; result: Promise<Result<CheckpointDetail>> }>();
193	  /** Rows each list shows, for lists that have grown past their first page. */
194	  private readonly limits = new Map<string, number>();
195	  /** Lists that stopped loading on scroll, and wait for a click on Load More. */
196	  readonly autoLoadPaused = new Set<string>();
197	  /**
198	   * Checkpoints the CLI could not find when asked, here or on the remote. A
199	   * commit records a checkpoint's ID, but the session data is uploaded
200	   * separately, and for these it was not. Cleared by a manual refresh.
201	   */
202	  readonly withoutData = new Set<string>();
203	  /** Authors the CLI named for checkpoints that no commit read so far carries, by checkpoint ID. */
204	  readonly checkpointAuthors = new Map<string, string>();
205	  /**
206	   * The prompt that opens each session, by session ID. A session's opening
207	   * prompt does not change, so a name is kept for as long as the window is
208	   * open. `name` is null for a session none of whose checkpoints stored a
209	   * transcript to read it from. `checkpoints` says how many the session had
210	   * then, so that the session is looked at again once it has more.
211	   */
212	  readonly sessionNames = new Map<string, { name: string | null; checkpoints: number }>();
213	  /** Unset until the Sessions view first asks, so nothing reads entire.io before then. */
214	  remoteSessions?: RemoteSessionList;
215	  /** Counts the reads of Entire's session list, so a late answer to an earlier one can be dropped. */
216	  remoteSessionReads = 0;
217	  /** The checkpoints Entire lists for a session, by session ID, for the sessions that were asked about. */
218	  readonly remoteCheckpoints = new Map<string, RemoteCheckpointRead>();
219	  /** Unset until the Trails view first asks, so nothing reads entire.io before then. */
220	  trails?: TrailList;
221	  /** Counts the reads of the trail list, so a late answer to an earlier one can be dropped. */
222	  trailReads = 0;
223	  /** Web pages of trails, by trail number, as `entire trail show` reported them. */
224	  readonly trailUrls = new Map<number, string>();
225	  /** Trails read in this window, so a trail panel can draw one at once while it reads it again. */
226	  readonly trailMemory = new TrailMemory();
227	
228	  constructor(readonly paths: RepoPaths) {
229	    this.name = path.basename(paths.root);
230	  }
231	
232	  get root(): string {
233	    return this.paths.root;
234	  }
235	
236	  get enabled(): boolean {
237	    return this.status?.enabled === true;
238	  }
239	
240	  /** How many rows of a list the views show. */
241	  limit(list: string): number {
242	    return this.limits.get(list) ?? PAGE_SIZE;
243	  }
244	
245	  showMore(list: string): void {
246	    this.limits.set(list, this.limit(list) + PAGE_SIZE);
247	  }
248	
249	  /** Drops what is kept about a list that no longer exists. */
250	  forgetList(list: string): void {
251	    this.limits.delete(list);
252	    this.autoLoadPaused.delete(list);
253	  }
254	
255	  /** Drops everything Entire said about the repository's sessions. An answer still on its way is ignored. */
256	  forgetRemoteSessions(): void {
257	    this.remoteSessions = undefined;
258	    this.remoteSessionReads += 1;
259	    this.remoteCheckpoints.clear();
260	  }
261	
262	  /** Drops everything read about the repository's trails. An answer still on its way is ignored. */
263	  forgetTrails(): void {
264	    if (this.trails) this.forgetList(this.trails.list);
265	    this.trails = undefined;
266	    this.trailReads += 1;
267	    this.trailUrls.clear();
268	    this.trailMemory.clear();
269	  }
270	}
271	
272	/** What a trail panel says while the `entire.trails.enabled` setting is off. */
273	export const TRAILS_OFF = 'Trails are turned off. Turn on the entire.trails.enabled setting to read them from Entire.';
274	
275	/**
276	 * Owns what the extension knows about each open repository and decides which
277	 * git and CLI calls run when.
278	 */
279	export class RepoManager implements vscode.Disposable {
280	  private readonly changed = new vscode.EventEmitter<void>();
281	  readonly onDidChange = this.changed.event;
282	
283	  repos: RepoContext[] = [];
284	  viewState: ViewState = 'loading';
285	  cli?: EntireCli;
286	  cliVersion?: CliVersion;
287	  readonly store: CheckpointStore;
288	
289	  /** The filter of the Trails view, shared by every repository in it. */
290	  trailFilter: TrailFilter = DEFAULT_TRAIL_FILTER;
291	
292	  private readonly cliLane = new Lane(4);
293	  /** Sessions whose opening prompt is being read, and the reads that wait their turn. */
294	  private readonly naming = new Set<string>();
295	  private readonly nameQueue: (() => Promise<void>)[] = [];
296	  private nameWorkers = 0;
297	  private namesTimer: NodeJS.Timeout | undefined;
298	  /** The latest history scan of each repository, which the next one waits for. */
299	  private readonly scans = new WeakMap<RepoContext, Promise<boolean>>();
300	  /** The latest page read of each trail list, which the next one waits for. */
301	  private readonly trailPageReads = new WeakMap<TrailList, Promise<boolean>>();
302	  /** The latest page read of each of Entire's session lists, which the next one waits for. */
303	  private readonly remoteSessionPageReads = new WeakMap<RemoteSessionList, Promise<boolean>>();
304	  private loadSequence = 0;
305	
306	  constructor(
307	    readonly git: Git,
308	    private readonly exec: Exec,
309	    private readonly log: vscode.LogOutputChannel,
310	  ) {
311	    this.store = new CheckpointStore(git);
312	  }
313	
314	  dispose(): void {
315	    for (const repo of this.repos) clearTimeout(repo.enrichmentTimer);
316	    clearTimeout(this.namesTimer);
317	    this.nameQueue.length = 0;
318	    this.changed.dispose();
319	  }
320	
321	  repoFor(root: string): RepoContext | undefined {
322	    return this.repos.find((repo) => repo.root === root);
323	  }
324	
325	  /** Resolves once the first load has settled, for panels restored at startup. */
326	  whenLoaded(): Promise<void> {
327	    if (this.viewState !== 'loading') return Promise.resolve();
328	    return new Promise((resolve) => {
329	      const subscription = this.onDidChange(() => {
330	        if (this.viewState === 'loading') return;
331	        subscription.dispose();
332	        resolve();
333	      });
334	    });
335	  }
336	
337	  /** Repositories that have Entire enabled, which are the ones the views show. */
338	  get enabledRepos(): RepoContext[] {
339	    return this.repos.filter((repo) => repo.enabled);
340	  }
341	
342	  webBase(): string {
343	    const setting = vscode.workspace.getConfiguration('entire').get<string>('webBaseUrl');
344	    return resolveWebBase(setting, process.env);
345	  }
346	
347	  /**
348	   * Finds the CLI and the repositories, then loads each one. A manual refresh
349	   * also reloads the full session list, which automatic refreshes never do.
350	   */
351	  async reload(options: { manual: boolean }): Promise<void> {
352	    const sequence = ++this.loadSequence;
353	    const stale = (): boolean => sequence !== this.loadSequence;
354	    const previous = new Map(this.repos.map((repo) => [repo.root, repo]));
355	    this.setState(this.repos.length === 0 ? 'loading' : this.viewState);
356	
357	    const folders = (vscode.workspace.workspaceFolders ?? []).filter(
358	      (folder) => folder.uri.scheme === 'file' || folder.uri.scheme === 'vscode-remote',
359	    );
360	    if (folders.length === 0) {
361	      this.replaceRepos([]);
362	      this.setState('noFolder');
363	      return;
364	    }
365	
366	    const repos: RepoContext[] = [];
367	    for (const folder of folders) {
368	      const paths = await this.git.repoPaths(folder.uri.fsPath);
369	      if (stale()) return;
370	      if (!paths.ok) {
371	        this.log.info(`${folder.uri.fsPath}: ${paths.failure.message} ${paths.failure.detail ?? ''}`.trim());
372	        continue;
373	      }
374	      if (repos.some((repo) => repo.root === paths.value.root)) continue;
375	      const existing = previous.get(paths.value.root);
376	      repos.push(existing ?? new RepoContext(paths.value));
377	    }
378	    this.replaceRepos(repos);
379	    if (repos.length === 0) {
380	      this.setState('notGit');
381	      return;
382	    }
383	
384	    const cwd = repos[0]?.root ?? os.homedir();
385	    const configured = vscode.workspace.getConfiguration('entire').get<string>('cliPath');
386	    const located = await locateCli(configured, {
387	      env: process.env,
388	      platform: process.platform,
389	      homedir: os.homedir(),
390	      isExecutable: isExecutableFile,
391	      probeLoginShell: loginShellProbe(this.exec, process.env, cwd),
392	    });
393	    if (stale()) return;
394	    if (!located) {
395	      this.cli = undefined;
396	      this.log.warn(
397	        configured?.trim()
398	          ? `entire.cliPath is set to "${configured}", but no executable exists there.`
399	          : 'The Entire CLI was not found on PATH, in common install locations, or through the login shell.',
400	      );
401	      this.setState('cliMissing');
402	      return;
403	    }
404	
405	    const cli = new EntireCli(located.path, this.exec, this.cliLane, (line) => this.log.info(line));
406	    const version = await cli.version(cwd);
407	    if (stale()) return;
408	    if (!version.ok) {
409	      this.cli = undefined;
410	      this.log.warn(`${located.path}: ${version.failure.message} ${version.failure.detail ?? ''}`.trim());
411	      this.setState('cliMissing');
412	      return;
413	    }
414	    this.cliVersion = version.value;
415	    this.log.info(`Using Entire CLI ${version.value.raw} at ${located.path} (found through ${located.source}).`);
416	    if (!isSupportedVersion(version.value)) {
417	      this.cli = undefined;
418	      this.log.warn(`Entire CLI ${version.value.raw} is older than the required ${MIN_CLI_VERSION_TEXT}.`);
419	      this.setState('cliTooOld');
420	      return;
421	    }
422	    this.cli = cli;
423	
424	    await Promise.all(repos.map((repo) => this.loadStatus(repo)));
425	    if (stale()) return;
426	    if (options.manual) {
427	      for (const repo of repos) {
428	        repo.trailUrls.clear();
429	        repo.trailMemory.clear();
430	        // Only lists the Trails view has already asked for. Nothing waits for them.
431	        if (repo.entireRepo && repo.trails) void this.loadTrails(repo);
432	      }
433	    }
434	    if (this.enabledRepos.length === 0) {
435	      this.setState('notEnabled');
436	      return;
437	    }
438	
439	    await Promise.all(
440	      this.enabledRepos.map(async (repo) => {
441	        repo.details.clear();
442	        repo.withoutData.clear();
443	        await this.loadGit(repo, { force: true });
444	        this.scheduleEnrichment(repo, { immediate: true });
445	        if (options.manual && repo.sessionRows !== undefined) await this.loadSessionRows(repo);
446	        if (options.manual && repo.remoteSessions !== undefined) {
447	          // Only a list the Sessions view has already asked for. Nothing waits for it.
448	          repo.remoteCheckpoints.clear();
449	          void this.loadRemoteSessions(repo);
450	        }
451	      }),
452	    );
453	    if (stale()) return;
454	    this.setState('ready');
455	  }
456	
457	  /** Re-reads HEAD and rebuilds the commit index when the branch tip moved. */
458	  async refreshGit(repo: RepoContext): Promise<void> {
459	    if (!repo.enabled || !this.cli) return;
460	    const changed = await this.loadGit(repo, { force: false });
461	    if (changed) {
462	      this.scheduleEnrichment(repo, { immediate: false });
463	      this.changed.fire();
464	    }
465	  }
466	
467	  /** Re-reads `entire status --json`, the only session source with no side effects. */
468	  async refreshStatus(repo: RepoContext): Promise<void> {
469	    if (!this.cli) return;
470	    const wasEnabled = repo.enabled;
471	    await this.loadStatus(repo);
472	    if (repo.enabled !== wasEnabled) {
473	      await this.reload({ manual: false });
474	      return;
475	    }
476	    this.changed.fire();
477	  }
478	
479	  /**
480	   * Shows one more page of a list. Three lists have more to read than they
481	   * hold: the commit list scans further back in history when the commits
482	   * already scanned run short, and the trail list and the session list ask
483	   * Entire for the next page.
484	   */
485	  async showMore(repo: RepoContext, list: string, options: { automatic: boolean } = { automatic: false }): Promise<void> {
486	    const trails = repo.trails?.list === list ? repo.trails : undefined;
487	    const sessions = list === LISTS.recentSessions && repo.remoteSessions !== undefined;
488	    const visible = (): number =>
489	      trails
490	        ? Math.min(repo.limit(list), this.shownTrails(trails).length)
491	        : sessions
492	          ? Math.min(repo.limit(list), this.sessions(repo).recent.length)
493	          : Math.min(repo.limit(LISTS.commits), repo.index?.commits.length ?? 0);
494	    const before = visible();
495	    repo.showMore(list);
496	    if (!options.automatic) repo.autoLoadPaused.delete(list);
497	    if (list === LISTS.commits || trails || sessions) {
498	      const read = trails
499	        ? await this.readMoreTrails(repo, trails)
500	        : sessions
501	          ? await this.readMoreRemoteSessions(repo)
502	          : await this.scanForCommits(repo);
503	      if (!read && !options.automatic) {
504	        void vscode.window.showWarningMessage(
505	          trails
506	            ? 'Entire could not load more trails.'
507	            : sessions
508	              ? 'Entire could not load more sessions.'
509	              : 'Entire could not read more of the commit history.',
510	        );
511	      }
512	      // A scan stops after a fixed stretch of history. When loading on scroll
513	      // finds no new row in that stretch, the Load More row is still in view
514	      // and would start the next scan at once, and so on to the first commit.
515	      // Stop there and leave the rest to a click. The same goes for trails:
516	      // for a page that fails to load, and for a read that finds no trail
517	      // the filter shows.
518	      if (options.automatic && (!read || visible() <= before)) repo.autoLoadPaused.add(list);
519	    }
520	    this.changed.fire();
521	  }
522	
523	  /**
524	   * Whether the extension may read trails. They are the one thing it reads
525	   * over the network, and the `entire.trails.enabled` setting turns them off.
526	   */
527	  get trailsEnabled(): boolean {
528	    return vscode.workspace.getConfiguration('entire').get<boolean>('trails.enabled', true);
529	  }
530	
531	  /** Repositories that Entire hosts, which are the ones the Trails view lists. None while trails are turned off. */
532	  get trailRepos(): RepoContext[] {
533	    if (!this.trailsEnabled) return [];
534	    // Trails live on entire.io, so a repository can have them before Entire is enabled in its clone.
535	    if (this.viewState !== 'ready' && this.viewState !== 'notEnabled') return [];
536	    return this.repos.filter((repo) => repo.entireRepo !== undefined);
537	  }
538	
539	  /**
540	   * Applies a change of the `entire.trails.enabled` setting. Turning trails
541	   * off hides the Trails view and drops what was read, so turning them on
542	   * again starts from a fresh read.
543	   */
544	  applyTrailsSetting(): void {
545	    if (!this.trailsEnabled) {
546	      for (const repo of this.repos) repo.forgetTrails();
547	    }
548	    this.trailsChanged();
549	  }
550	
551	  /**
552	   * The trails of a list that the filter shows. The CLI lists by status, so a
553	   * filter on a phase keeps the trails in that phase out of the ones read so
554	   * far.
555	   */
556	  shownTrails(list: TrailList): TrailSummary[] {
557	    const filter = this.trailFilter;
558	    return filter.phase ? list.trails.filter((trail) => inTrailFilter(trail, filter)) : list.trails;
559	  }
560	
561	  /**
562	   * What the Trails view shows. With one repository, a list with no rows
563	   * leaves the view empty and this says why. With several, each repository
564	   * has a row of its own and says so under it.
565	   */
566	  trailsState(): TrailsState {
567	    const repos = this.trailRepos;
568	    if (repos.length !== 1) return 'ready';
569	    const list = repos[0]?.trails;
570	    if (!list || (list.loading && list.trails.length === 0)) return 'loading';
571	    if (this.shownTrails(list).length > 0) return 'ready';
572	    if (list.failure) {
573	      if (list.failure.kind === 'notLoggedIn') return 'loggedOut';
574	      return list.failure.kind === 'noAccess' ? 'noAccess' : 'failed';
575	    }
576	    // No row passes the filter yet, but the CLI has more to list: the view keeps its Load More row.
577	    return list.nextPageToken ? 'ready' : 'empty';
578	  }
