590	  /**
591	   * Changes which trails the Trails view shows: every trail, the open ones,
592	   * the closed ones, or the open ones in one phase.
593	   */
594	  async setTrailFilter(filter: TrailFilter): Promise<void> {
595	    if (trailFilterKey(filter) === trailFilterKey(this.trailFilter)) return;
596	    this.trailFilter = filter;
597	    this.trailsChanged();
598	    await Promise.all(
599	      this.trailRepos.map((repo) => {
600	        const list = repo.trails;
601	        // A phase is matched here, so the trails already read for the status serve any phase of it.
602	        const reusable = list !== undefined && list.status === filter.status && !list.loading && !list.failure;
603	        return reusable ? this.refilterTrails(repo, list) : this.loadTrails(repo);
604	      }),
