613	  private async readFirstTrails(repo: RepoContext): Promise<void> {
614	    const cli = this.cli;
615	    const entireRepo = repo.entireRepo;
616	    if (!cli || !entireRepo || !this.trailsEnabled) return;
617	    const read = ++repo.trailReads;
618	    const filter = this.trailFilter;
619	    const list: TrailList = {
620	      list: LISTS.trails(trailFilterKey(filter), read),
621	      status: filter.status,
622	      trails: [],
623	      loading: true,
624	    };
625	    // A refresh keeps the rows on screen until the fresh ones arrive. Rows of
626	    // another status go at once: they would sit under the wrong heading.
627	    const previous = repo.trails;
628	    if (!previous || previous.status !== list.status || previous.trails.length === 0) {
629	      repo.trails = list;
630	      this.trailsChanged();
631	    }
632	    const page = await cli.listTrails(
633	      repo.root,
634	      { project: trailProject(entireRepo), repo: trailRepo(entireRepo) },
635	      list.status,
636	      PAGE_SIZE,
637	    );
638	    if (read !== repo.trailReads) return;
639	    list.loading = false;
640	    if (page.ok) {
641	      addTrailPage(list, page.value);
642	    } else {
643	      list.failure = page.failure;
644	      this.log.warn(`${repo.name}: ${page.failure.message} ${page.failure.detail ?? ''}`.trim());
645	    }
646	    if (previous && previous !== list) repo.forgetList(previous.list);
647	    repo.trails = list;
648	    this.trailsChanged();
649	    // With a filter on a phase, the first page may hold few trails that pass it.
650	    await this.readMoreTrails(repo, list);
651	    this.trailsChanged();
652	  }
