654	  /** Shows the trails already read under a filter that has changed, from the first page of rows. */
655	  private async refilterTrails(repo: RepoContext, list: TrailList): Promise<void> {
656	    repo.forgetList(list.list);
657	    list.list = LISTS.trails(trailFilterKey(this.trailFilter), ++repo.trailReads);
658	    this.trailsChanged();
659	    await this.readMoreTrails(repo, list);
660	    this.trailsChanged();
661	  }
