663	  /**
664	   * Names a trail for a CLI call: by its ID when the caller, the Trails view,
665	   * or an earlier read has it, and by its number otherwise.
666	   */
667	  trailRef(repo: RepoContext, trail: number, id?: string): TrailRef {
668	    const known =
669	      id ?? repo.trails?.trails.find((listed) => listed.number === trail)?.id ?? repo.trailMemory.idOf(trail);
670	    return known ? { number: trail, id: known } : { number: trail };
