673	  /**
674	   * Reads one trail from entire.io: its changes, their merge gates and CI
675	   * runs, and its page on the web. The trail is kept for the views and for
676	   * the next panel that opens it.
677	   */
678	  async showTrail(repo: RepoContext, trail: TrailRef, signal?: AbortSignal): Promise<Result<TrailDetail>> {
679	    const cli = this.cli;
680	    if (!cli) return fail('cliMissing', 'The Entire CLI is not available.');
681	    if (!this.trailsEnabled) return fail('noAccess', TRAILS_OFF);
682	    if (!repo.entireRepo) {
683	      return fail('noAccess', 'Trails are available when the origin remote uses the entire:// scheme.');
684	    }
685	    const hosted = repo.entireRepo;
686	    const detail = await cli.showTrail(repo.root, trailProject(hosted), trail, signal);
687	    // An answer for an origin that has since changed belongs to another repository.
688	    if (JSON.stringify(repo.entireRepo) !== JSON.stringify(hosted)) return detail;
689	    if (detail.ok) {
690	      if (detail.value.url) repo.trailUrls.set(detail.value.number, detail.value.url);
691	      repo.trailMemory.keepDetail(detail.value);
692	    } else if (detail.failure.kind === 'notFound') {
693	      repo.trailMemory.forget(trail.number);
694	    }
695	    if (!detail.ok && detail.failure.kind !== 'aborted') {
696	      this.log.warn(`Trail ${trail.number}: ${detail.failure.message} ${detail.failure.detail ?? ''}`.trim());
697	    }
698	    return detail;
699	  }
