701	  /**
702	   * The web page of a trail. It comes from the CLI: a trail's address is not
703	   * derived from its number here, because the CLI asks callers not to.
704	   */
705	  async trailUrl(repo: RepoContext, trail: number): Promise<string | undefined> {
706	    const known = repo.trailUrls.get(trail);
707	    if (known) return known;
708	    const detail = await this.showTrail(repo, this.trailRef(repo, trail));
709	    return detail.ok ? detail.value.url : undefined;
