712	  /**
713	   * Asks the CLI for pages until the list shows as many trails as its rows
714	   * allow, the CLI has no more, or one read's worth of pages has been asked
715	   * for. Reads of one list run one after another, because each continues
716	   * from the token the one before it returned.
717	   */
718	  private readMoreTrails(repo: RepoContext, list: TrailList): Promise<boolean> {
719	    // Nothing to read: say so without touching the view's progress bar.
720	    if (!list.nextPageToken || this.shownTrails(list).length >= repo.limit(list.list)) {
721	      return this.trailPageReads.get(list) ?? Promise.resolve(true);
722	    }
723	    const read = async (): Promise<boolean> => {
724	      const cli = this.cli;
725	      const entireRepo = repo.entireRepo;
726	      // The list was replaced, or its rows were restarted under another filter, while this waited.
727	      const name = list.list;
728	      const current = (): boolean => repo.trails === list && list.list === name;
729	      if (!current()) return true;
730	      if (!cli || !entireRepo) return false;
731	      let replaced = false;
732	      const okay = await readTrailPages(
733	        list,
734	        async (pageToken) => {
735	          const page = await cli.listTrails(
736	            repo.root,
737	            { project: trailProject(entireRepo), repo: trailRepo(entireRepo) },
738	            list.status,
739	            PAGE_SIZE,
740	            pageToken,
741	          );
742	          if (repo.trails !== list) {
743	            replaced = true;
744	            return undefined;
745	          }
746	          if (!page.ok) {
747	            this.log.warn(`${repo.name}: ${page.failure.message} ${page.failure.detail ?? ''}`.trim());
748	            return undefined;
749	          }
750	          return page.value;
751	        },
752	        () => !current() || this.shownTrails(list).length >= repo.limit(list.list),
753	        // Rows appear as each page arrives, which matters when a read takes several.
754	        { onPage: () => this.changed.fire() },
755	      );
756	      return okay || replaced;
757	    };
758	    const next = (this.trailPageReads.get(list) ?? Promise.resolve(true)).then(read, read);
759	    this.trailPageReads.set(list, next);
760	    return this.withViewProgress('entire.trails', next);
761	  }
