763	  /**
764	   * Shows a view's progress bar while Entire is read for it. Each call to
765	   * the CLI takes seconds, and a filter on a trail phase can take several.
766	   */
767	  private withViewProgress<T>(viewId: string, work: Promise<T>): Promise<T> {
768	    const settled = work.then(
769	      () => undefined,
770	      () => undefined,
771	    );
772	    // The bar is a courtesy. An editor that cannot show it still gets the trails.
773	    try {
774	      Promise.resolve(vscode.window.withProgress({ location: { viewId } }, () => settled)).catch(
775	        () => {},
776	      );
777	    } catch {
778	      // Nothing to do: the read goes on without the bar.
779	    }
780	    return work;
781	  }
