800	  private async readFirstRemoteSessions(repo: RepoContext): Promise<void> {
801	    const cli = this.cli;
802	    if (!cli || !repo.enabled || !repo.entireRepo) return;
803	    const read = ++repo.remoteSessionReads;
804	    const list: RemoteSessionList = { sessions: new Map(), loading: true };
805	    // A refresh keeps the names on screen until the fresh ones arrive.
806	    const previous = repo.remoteSessions;
807	    if (!previous) {
808	      repo.remoteSessions = list;
809	      this.changed.fire();
810	    }
811	    const page = await cli.remoteSessions(repo.root, REMOTE_SESSIONS_PAGE);
812	    if (read !== repo.remoteSessionReads) return;
813	    list.loading = false;
814	    if (page.ok) {
815	      addRemoteSessions(list, page.value);
816	    } else {
817	      list.failure = page.failure;
818	      this.log.warn(`${repo.name}: ${page.failure.message} ${page.failure.detail ?? ''}`.trim());
819	    }
820	    if (!page.ok && previous && previous.sessions.size > 0) {
821	      // The names read before still hold. Only the reason for the failure is new.
822	      previous.failure = page.failure;
823	    } else {
824	      repo.remoteSessions = list;
825	    }
826	    this.changed.fire();
827	    // A list that had grown past its first page keeps its rows named.
828	    await this.readMoreRemoteSessions(repo);
829	  }
