831	  /**
832	   * Asks Entire for pages until its list holds as many sessions as the
833	   * Sessions view shows rows, or Entire has no more. Entire lists the most
834	   * recent sessions first, and so does the view, so that many sessions name
835	   * every row on show that Entire knows.
836	   *
837	   * Reads of one list run one after another, because each continues from
838	   * the cursor the one before it returned.
839	   */
840	  private readMoreRemoteSessions(repo: RepoContext): Promise<boolean> {
841	    const list = repo.remoteSessions;
842	    if (!list) return Promise.resolve(true);
843	    const enough = (): boolean => !list.nextCursor || list.sessions.size >= repo.limit(LISTS.recentSessions);
844	    // Nothing to read: say so without touching the view's progress bar.
845	    if (enough()) return this.remoteSessionPageReads.get(list) ?? Promise.resolve(true);
846	    const read = async (): Promise<boolean> => {
847	      for (let pages = 0; pages < MAX_REMOTE_SESSION_PAGES_PER_READ; pages += 1) {
848	        // The list was replaced by a fresh read while this waited.
849	        if (repo.remoteSessions !== list || enough()) return true;
850	        const cli = this.cli;
851	        const cursor = list.nextCursor;
852	        if (!cli || !cursor) return false;
853	        const page = await cli.remoteSessions(repo.root, REMOTE_SESSIONS_PAGE, cursor);
854	        if (repo.remoteSessions !== list) return true;
855	        if (!page.ok) {
856	          this.log.warn(`${repo.name}: ${page.failure.message} ${page.failure.detail ?? ''}`.trim());
857	          return false;
858	        }
859	        addRemoteSessions(list, page.value, cursor);
860	        // Names appear as each page arrives.
861	        this.changed.fire();
862	      }
863	      return true;
864	    };
865	    const next = (this.remoteSessionPageReads.get(list) ?? Promise.resolve(true)).then(read, read);
866	    this.remoteSessionPageReads.set(list, next);
867	    return this.withViewProgress('entire.sessions', next);
868	  }
