886	  /**
887	   * The checkpoints of a session, newest first. The clone knows the ones on
888	   * the checked-out branch. When Entire counts more than that, its list of
889	   * the session's checkpoints is read as well, once, and the two are shown
890	   * as one list.
891	   *
892	   * Entire sends that list with the session's transcript, which takes
893	   * seconds for a long session. So the checkpoints the clone knows are
894	   * returned at once, and the views are redrawn when Entire's arrive. With
895	   * `wait`, or for a session the clone knows no checkpoint of, the call
896	   * waits for Entire instead.
897	   */
898	  async sessionCheckpoints(
899	    repo: RepoContext,
900	    sessionId: string,
901	    options: { wait?: boolean; signal?: AbortSignal } = {},
902	  ): Promise<SessionCheckpoint[]> {
903	    const entry = this.sessionEntry(repo, sessionId);
904	    if (!entry) return [];
905	    const short = entry.listedCheckpoints !== undefined && entry.listedCheckpoints > entry.checkpoints.length;
906	    if (!short || entry.checkpointsFromEntire) return entry.checkpoints;
907	    const read = this.readRemoteCheckpoints(repo, sessionId, options.signal);
908	    if (!options.wait && entry.checkpoints.length > 0) return entry.checkpoints;
909	    await read;
910	    return this.sessionEntry(repo, sessionId)?.checkpoints ?? entry.checkpoints;
911	  }
912	
913	  /**
914	   * Entire's list of a session's checkpoints, read once. The views are
915	   * redrawn when it arrives. A read that fails is tried again after a while.
916	   */
917	  private readRemoteCheckpoints(
918	    repo: RepoContext,
919	    sessionId: string,
920	    signal?: AbortSignal,
921	  ): Promise<RemoteCheckpoint[] | undefined> {
922	    const known = repo.remoteCheckpoints.get(sessionId);
923	    if (known && (known.failedAt === undefined || Date.now() - known.failedAt < REMOTE_CHECKPOINTS_RETRY_MS)) {
924	      return known.read;
925	    }
926	    const cli = this.cli;
927	    if (!cli || !repo.entireRepo) return Promise.resolve(undefined);
928	    const slot: RemoteCheckpointRead = {
929	      read: cli.remoteSessionCheckpoints(repo.root, sessionId, signal).then((result) => {
930	        if (repo.remoteCheckpoints.get(sessionId) !== slot) return undefined;
931	        if (!result.ok) {
932	          if (result.failure.kind === 'aborted') {
933	            // The panel that asked was closed. The next one to ask reads again.
934	            repo.remoteCheckpoints.delete(sessionId);
935	          } else {
936	            slot.failedAt = Date.now();
937	            this.log.warn(`Session ${sessionId}: ${result.failure.message} ${result.failure.detail ?? ''}`.trim());
938	          }
939	          return undefined;
940	        }
941	        slot.checkpoints = result.value;
942	        this.changed.fire();
943	        return result.value;
944	      }),
945	    };
946	    repo.remoteCheckpoints.set(sessionId, slot);
947	    return this.withViewProgress('entire.sessions', slot.read);
948	  }
