962	  /**
963	   * Scans history until the index holds as many linked commits as the commit
964	   * list shows. Scans of one repository run one after another: each starts
965	   * where the index stops, so two at once would read the same stretch twice
966	   * and list its commits twice.
967	   */
968	  private scanForCommits(repo: RepoContext): Promise<boolean> {
969	    const scan = async (): Promise<boolean> => {
970	      const index = repo.index;
971	      const missing = index ? repo.limit(LISTS.commits) - index.commits.length : 0;
972	      if (!index || index.exhausted || missing <= 0) return true;
973	      return loadPage(index, (skip, count) => this.fetchWindow(repo, index.tipSha, skip, count), missing);
974	    };
