980	  /**
981	   * Loads the full session list. The CLI prunes session state idle for more
982	   * than seven days while it lists, so this runs only when the Sessions view
983	   * is first shown and on a manual refresh.
984	   */
985	  async loadSessionRows(repo: RepoContext): Promise<void> {
986	    if (!this.cli || !repo.enabled) return;
987	    const rows = await this.cli.sessionList(repo.root);
988	    if (rows.ok) {
989	      repo.sessionRows = rows.value;
990	    } else {
991	      repo.sessionRows ??= [];
992	      this.log.warn(`${repo.name}: ${rows.failure.message} ${rows.failure.detail ?? ''}`.trim());
993	    }
994	    this.changed.fire();
995	  }
