1	import type { TrailChange, TrailCheckRun, TrailEvent, TrailGate, TrailPage, TrailSummary } from './schemas';
2	
3	/**
4	 * The parts of an `entire://` remote that name a repository on Entire.
5	 * `EntireRepo` in `webLinks.ts` fits it. It is declared here so the panel's
6	 * page, which shares this module, does not pull in code that needs Node.
7	 */
8	export interface HostedRepo {
9	  /** `gh` for a GitHub mirror, `et` for an Entire-native repository. */
10	  forge: string;
11	  /** GitHub owner, or Entire project. */
12	  owner: string;
13	  repo: string;
14	}
15	
16	/** The lifecycle status of a trail. A trail is open until someone closes it. */
17	export type TrailStatus = 'open' | 'closed';
18	
19	/** What the CLI can list: the trails of one status, or the trails of both. */
20	export type TrailListStatus = TrailStatus | 'all';
21	
22	/**
23	 * Which trails the Trails view shows.
24	 *
25	 * A trail has a status, and an open trail is also in a phase that follows its
26	 * work: planning, building, or complete. The CLI lists by status and cannot
27	 * list by phase, so a phase is matched here, against the trails read so far.
28	 */
29	export interface TrailFilter {
30	  status: TrailListStatus;
31	  /** Only open trails in this phase. */
32	  phase?: string;
33	}
34	
35	export const DEFAULT_TRAIL_FILTER: TrailFilter = { status: 'open' };
36	
37	/** The phases of an open trail that the filter offers by name. */
38	export const OPEN_PHASES: readonly string[] = ['planning', 'building', 'complete'];
39	
40	const PHASE_NAME = /^[a-z][a-z0-9_-]{0,39}$/;
41	
42	/** A filter as one string: `all`, `open`, `closed`, or `open:<phase>`. */
43	export function trailFilterKey(filter: TrailFilter): string {
44	  return filter.phase ? `${filter.status}:${filter.phase}` : filter.status;
45	}
46	
47	/** Reads a filter back from its key, or returns undefined for anything else. */
48	export function readTrailFilter(key: unknown): TrailFilter | undefined {
49	  if (typeof key !== 'string') return undefined;
50	  if (key === 'all' || key === 'open' || key === 'closed') return { status: key };
51	  const [status, phase, ...rest] = key.split(':');
52	  // Only an open trail has a phase to tell apart. A closed one is in the closed phase.
53	  if (status !== 'open' || !phase || rest.length > 0 || !PHASE_NAME.test(phase)) return undefined;
54	  return { status: 'open', phase };
55	}
56	
57	/** The filter's name: "All", "Open", "Closed", or the phase, such as "Building". */
58	export function trailFilterLabel(filter: TrailFilter): string {
59	  if (filter.phase) return sentenceCase(filter.phase);
60	  return filter.status === 'all' ? 'All' : filter.status === 'closed' ? 'Closed' : 'Open';
61	}
62	
63	/** What to say when no trail matches the filter. */
64	export function noTrailsText(filter: TrailFilter): string {
65	  if (filter.phase) return `No open trails in the ${words(filter.phase)} phase touch this repository.`;
66	  if (filter.status === 'all') return 'No trails touch this repository.';
67	  return `No ${filter.status} trails touch this repository.`;
68	}
69	
70	/**
71	 * The filters to offer: every status the CLI lists by, then each phase of an
72	 * open trail. `seen` adds the phases that trails read so far are in, so a
73	 * phase that a later CLI introduces can still be picked.
74	 */
75	export function trailFilters(seen: Iterable<string | undefined> = []): TrailFilter[] {
76	  const extra = [...new Set(seen)]
77	    .filter((phase): phase is string => phase !== undefined && PHASE_NAME.test(phase))
78	    .filter((phase) => phase !== 'closed' && !OPEN_PHASES.includes(phase))
79	    .sort();
80	  return [
81	    { status: 'all' },
82	    { status: 'open' },
83	    { status: 'closed' },
84	    ...[...OPEN_PHASES, ...extra].map((phase): TrailFilter => ({ status: 'open', phase })),
85	  ];
86	}
87	
88	/** Whether a trail the CLI listed for the filter's status also passes the rest of the filter. */
89	export function inTrailFilter(trail: Pick<TrailSummary, 'phase'>, filter: TrailFilter): boolean {
90	  return filter.phase === undefined || trail.phase === filter.phase;
91	}
92	
93	/** The trails read so far for one status, and where the CLI's list continues. */
94	export interface TrailPages {
95	  /** Most recent activity first, as the CLI lists them. */
96	  trails: TrailSummary[];
97	  /** Present while the CLI has more trails to list. */
98	  nextPageToken?: string;
99	  /** How many trails the CLI has for the status in all, when it says. */
100	  total?: number;
101	}
102	
103	/** Adds a page to the trails read so far, and returns how many of its trails were new. */
104	export function addTrailPage(list: TrailPages, page: TrailPage): number {
105	  // A trail moves to the front when it sees activity, so it can turn up again on a later page.
106	  const known = new Set(list.trails.map((trail) => trail.number));
107	  const fresh = page.trails.filter((trail) => !known.has(trail.number));
108	  list.trails.push(...fresh);
109	  if (page.nextPageToken) list.nextPageToken = REDACTED;
110	  else delete list.nextPageToken;
111	  if (page.total !== undefined) list.total = page.total;
112	  return fresh.length;
113	}
114	
115	/**
116	 * Pages one read may ask for. A phase can be rare among the open trails, and
117	 * without a limit a filter on it would read every page there is in one go.
118	 */
119	export const MAX_TRAIL_PAGES_PER_READ = 4;
120	
121	/**
122	 * Reads further pages until `enough()` says the list holds what is wanted,
123	 * the CLI has no more, or `maxPages` have been read. `fetch` returns
124	 * undefined when a page could not be read, and the result is then false.
125	 */
126	export async function readTrailPages(
127	  list: TrailPages,
128	  fetch: (pageToken: string) => Promise<TrailPage | undefined>,
129	  enough: () => boolean,
130	  options: { maxPages?: number; onPage?: () => void } = {},
131	): Promise<boolean> {
132	  const maxPages = options.maxPages ?? MAX_TRAIL_PAGES_PER_READ;
133	  for (let read = 0; read < maxPages && list.nextPageToken && !enough(); read += 1) {
134	    const token = list.nextPageToken;
135	    const page = await fetch(token);
136	    if (!page) return false;
137	    const added = addTrailPage(list, page);
138	    // A page that brings nothing new and points back at itself would repeat without end.
139	    if (added === 0 && list.nextPageToken === token) delete list.nextPageToken;
140	    options.onPage?.();
141	  }
142	  return true;
143	}
144	
145	/** The CLI's `--project` argument for a repository: `gh/<owner>` or `et/<project>`. */
146	export function trailProject(repo: HostedRepo): string {
147	  return `${repo.forge}/${repo.owner}`;
148	}
149	
150	/** The CLI's `--repo` argument for a repository. */
151	export function trailRepo(repo: HostedRepo): string {
152	  return `${repo.forge}/${repo.owner}/${repo.repo}`;
153	}
154	
155	/** A trail's ID on Entire is a ULID: 26 characters of Crockford base 32. */
156	const TRAIL_ID = /^[0-9A-HJKMNP-TV-Z]{26}$/;
157	
158	export function isTrailId(value: unknown): value is string {
159	  return typeof value === 'string' && TRAIL_ID.test(value);
160	}
161	
162	/**
163	 * How a CLI call names a trail. Given a number, the CLI first looks up the
164	 * trail's ID, which costs a request to entire.io. A call that already has
165	 * the ID passes it and skips that lookup.
166	 */
167	export interface TrailRef {
168	  /** The trail's number in its project. */
169	  number: number;
170	  id?: string;
171	}
172	
173	/** A change, named the way the CLI takes it: `<repository>/<number>`. */
174	export interface ChangeRef {
175	  repository: string;
176	  number: number;
177	}
178	
179	/**
180	 * What a timeline call reads: one change, or a trail, for which the CLI
181	 * picks the change. Its pick is certain only for a trail with one change:
182	 * with several open ones it exits with an error, and its reply does not say
183	 * which change it read.
184	 */
185	export type TimelineOf = ChangeRef | { trail: TrailRef };
186	
187	export function changeRef(change: ChangeRef): ChangeRef {
188	  return { repository: change.repository, number: change.number };
189	}
190	
191	export function sameChange(a: ChangeRef, b: ChangeRef): boolean {
192	  return a.repository === b.repository && a.number === b.number;
193	}
194	
195	/** Whether a change is a branch of this repository. A trail can span several. */
196	export function isInRepo(change: TrailChange, repo: HostedRepo): boolean {
197	  return change.repository.toLowerCase() === repo.repo.toLowerCase();
198	}
199	
200	/** Whether a change is the branch that is checked out in this repository. */
201	export function isCheckedOut(change: TrailChange, repo: HostedRepo, branch: string | undefined): boolean {
202	  return branch !== undefined && change.branch === branch && isInRepo(change, repo);
203	}
204	
205	/**
206	 * Position of the change that stands for a trail in one repository: the one
207	 * on the checked-out branch, then the first one in the repository, then the
208	 * first one. -1 when the trail has no changes.
209	 */
210	export function primaryChange(changes: readonly TrailChange[], repo: HostedRepo, branch: string | undefined): number {
211	  const here = changes.map((change, position) => ({ change, position })).filter(({ change }) => isInRepo(change, repo));
212	  const current = branch ? here.find(({ change }) => change.branch === branch) : undefined;
213	  if (current) return current.position;
214	  if (here[0]) return here[0].position;
215	  return changes.length > 0 ? 0 : -1;
216	}
217	
218	/** How a gate or a CI run stands, reduced to what the views draw. */
219	export type Outcome = 'passed' | 'failed' | 'pending' | 'skipped';
