1	import path from 'node:path';
2	import * as vscode from 'vscode';
3	import type { CheckpointTree, StoredSession } from '../../core/checkpointStore';
4	import { headline } from '../../core/format';
5	import { totalTokens, type CheckpointDetail } from '../../core/schemas';
6	import { parseCliText } from '../../core/transcript/cliText';
7	import { toolInputText, toWireTurn, type FullTurn, type ParsedTranscript } from '../../core/transcript/model';
8	import { parseCompactTranscript } from '../../core/transcript/normalize';
9	import { openingPrompt } from '../../core/transcript/prompts';
10	import { isCheckpointId, isCommitSha, type CommitRecord } from '../../core/trailers';
11	import {
12	  PROTOCOL_VERSION,
13	  isWebviewMessage,
14	  type DetailTarget,
15	  type HeaderFile,
16	  type HeaderLocalSession,
17	  type HeaderSession,
18	  type HostMessage,
19	  type PanelHeader,
20	  type TranscriptInfo,
21	  type WebviewMessage,
22	  type WireTurn,
23	} from '../../shared/protocol';
24	import type { Actions } from '../actions';
25	import type { RepoContext, RepoManager, SessionEntry } from '../repoManager';
26	import type { DetailView } from '../views/nodes';
27	import { panelHtml } from './html';
28	
29	const TURNS_PER_MESSAGE = 100;
30	/** Tool inputs and results beyond this size open in an editor instead. */
31	const BODY_LIMIT = 256 * 1024;
32	const IMAGE_LIMIT = 8 * 1024 * 1024;
33	const IMAGE_TYPES: Record<string, string> = {
34	  png: 'image/png',
35	  jpg: 'image/jpeg',
36	  jpeg: 'image/jpeg',
37	  gif: 'image/gif',
38	  webp: 'image/webp',
39	};
40	
41	/** Everything the host keeps for the panel's current target. */
42	interface Loaded {
43	  repo: RepoContext;
44	  header: PanelHeader;
45	  info: TranscriptInfo;
46	  turns: FullTurn[];
47	  wire: WireTurn[];
48	  detail?: CheckpointDetail;
49	  checkpointId?: string;
50	  commit?: CommitRecord;
51	  /** Slot of the selected session inside the checkpoint. */
52	  sessionIndex?: number;
53	  sessionId?: string;
54	  /** The checkpoints just before and after this one in the selected session. */
55	  neighbors?: { previous?: string; next?: string };
56	  tree?: CheckpointTree;
57	  stored?: StoredSession;
58	}
59	
60	/** Validates a target that came back from a restored webview. */
61	export function readDetailTarget(value: unknown): DetailTarget | undefined {
62	  if (typeof value !== 'object' || value === null) return undefined;
63	  const raw = value as Record<string, unknown>;
64	  if (typeof raw.repoRoot !== 'string' || (raw.mode !== 'checkpoint' && raw.mode !== 'session')) return undefined;
65	  const target: DetailTarget = { repoRoot: raw.repoRoot, mode: raw.mode };
66	  if (typeof raw.checkpointId === 'string' && isCheckpointId(raw.checkpointId)) target.checkpointId = raw.checkpointId;
67	  if (typeof raw.commitSha === 'string' && isCommitSha(raw.commitSha)) target.commitSha = raw.commitSha;
68	  if (typeof raw.sessionId === 'string' && raw.sessionId.length <= 128) target.sessionId = raw.sessionId;
69	  if (target.mode === 'checkpoint' && !target.checkpointId) return undefined;
70	  if (target.mode === 'session' && !target.sessionId) return undefined;
71	  return target;
72	}
73	
74	/** Drives one detail panel: loads its data and answers the webview's requests. */
75	export class PanelController implements vscode.Disposable {
76	  private loaded?: Loaded;
77	  private abort = new AbortController();
78	  private loadSequence = 0;
79	  private ready = false;
80	  private error?: { message: string; canRetry: boolean };
81	  /** A session the user picked in the panel, which overrides the target's preselection. */
82	  private pickedPosition?: number;
83	  private disposed = false;
84	  private readonly subscriptions: vscode.Disposable[] = [];
85	  private readonly disposeEmitter = new vscode.EventEmitter<void>();
86	  readonly onDidDispose = this.disposeEmitter.event;
87	  private readonly shownEmitter = new vscode.EventEmitter<DetailTarget>();
88	  /**
89	   * Fires when the tab moves on by itself, with what it now shows: another
90	   * checkpoint of the session, or another session of the checkpoint. The
91	   * view the tab was opened from moves its selection to match.
92	   */
93	  readonly onDidChangeShown = this.shownEmitter.event;
94	  /** The view whose row the tab was opened from. Unset for a tab opened from elsewhere, such as a trail. */
95	  origin?: DetailView;
96	
97	  constructor(
98	    readonly panel: vscode.WebviewPanel,
99	    private readonly manager: RepoManager,
100	    private readonly actions: Actions,
101	    extensionUri: vscode.Uri,
102	    private target: DetailTarget,
103	  ) {
104	    panel.webview.options = {
105	      enableScripts: true,
106	      localResourceRoots: [vscode.Uri.joinPath(extensionUri, 'dist', 'webview')],
107	    };
108	    panel.webview.html = panelHtml(panel.webview, extensionUri);
109	    this.subscriptions.push(
110	      panel.webview.onDidReceiveMessage((message: unknown) => void this.onMessage(message)),
111	      panel.onDidDispose(() => this.dispose()),
112	    );
113	    void this.load();
114	  }
115	
116	  dispose(): void {
117	    if (this.disposed) return;
118	    this.disposed = true;
119	    this.abort.abort();
120	    for (const subscription of this.subscriptions) subscription.dispose();
121	    this.disposeEmitter.fire();
122	    this.disposeEmitter.dispose();
123	    this.shownEmitter.dispose();
124	  }
125	
126	  /** True once the page's script has run and asked for data. */
127	  get webviewReady(): boolean {
128	    return this.ready;
129	  }
130	
131	  /** What the panel currently shows, for the extension-host tests. */
132	  snapshot(): { header: PanelHeader; transcript: TranscriptInfo; turns: number } | { error: string } | undefined {
133	    if (this.error) return { error: this.error.message };
134	    if (!this.loaded) return undefined;
135	    return { header: this.loaded.header, transcript: this.loaded.info, turns: this.loaded.wire.length };
136	  }
137	
138	  /** Moves to the checkpoint before or after this one in the selected session, when there is one. */
139	  step(direction: 'previous' | 'next'): void {
140	    const loaded = this.loaded;
141	    // The checkpoint comes from the host's own index, never from the page.
142	    const checkpointId = loaded?.neighbors?.[direction];
143	    if (!loaded || !checkpointId) return;
144	    this.show({
145	      repoRoot: loaded.repo.root,
146	      mode: 'checkpoint',
147	      checkpointId,
148	      ...(loaded.sessionId ? { sessionId: loaded.sessionId } : {}),
149	    });
150	    this.shownEmitter.fire(this.target);
151	  }
152	
153	  /** Shows another session of the checkpoint: the one at `position` among its sessions. */
154	  selectSession(position: number): void {
155	    const loaded = this.loaded;
156	    const session = loaded?.detail?.sessions[position];
157	    if (!loaded?.checkpointId || !session) return;
158	    this.pickedPosition = position;
159	    void this.load();
160	    this.shownEmitter.fire({
161	      repoRoot: loaded.repo.root,
162	      mode: 'checkpoint',
163	      checkpointId: loaded.checkpointId,
164	      ...(loaded.commit ? { commitSha: loaded.commit.sha } : {}),
165	      ...(session.sessionId ? { sessionId: session.sessionId } : {}),
166	    });
167	  }
168	
169	  /** Points the panel at something else, reusing the tab. */
170	  show(target: DetailTarget): void {
171	    this.target = target;
172	    this.pickedPosition = undefined;
173	    void this.load();
174	  }
175	
176	  private post(message: HostMessage): void {
177	    if (this.ready && !this.disposed) void this.panel.webview.postMessage(message);
178	  }
179	
180	  private sendLoaded(): void {
181	    const loaded = this.loaded;
182	    if (!loaded) return;
183	    this.post({
184	      type: 'init',
185	      protocol: PROTOCOL_VERSION,
186	      header: loaded.header,
187	      transcript: loaded.info,
188	      restore: this.target,
189	    });
190	    if (loaded.wire.length === 0) {
191	      this.post({ type: 'turns', turns: [], done: true });
192	      return;
193	    }
194	    for (let from = 0; from < loaded.wire.length; from += TURNS_PER_MESSAGE) {
195	      const turns = loaded.wire.slice(from, from + TURNS_PER_MESSAGE);
196	      this.post({ type: 'turns', turns, done: from + TURNS_PER_MESSAGE >= loaded.wire.length });
197	    }
198	  }
199	
200	  private showError(message: string, canRetry: boolean): void {
201	    this.loaded = undefined;
202	    this.error = { message, canRetry };
203	    this.post({ type: 'error', message, canRetry });
204	  }
205	
206	  private async load(): Promise<void> {
207	    const sequence = ++this.loadSequence;
208	    const stale = (): boolean => sequence !== this.loadSequence || this.disposed;
209	    this.abort.abort();
210	    this.abort = new AbortController();
211	    const signal = this.abort.signal;
212	    this.loaded = undefined;
213	    this.error = undefined;
214	    this.post({ type: 'loading', title: 'Loading' });
215	
216	    await this.manager.whenLoaded();
217	    if (stale()) return;
218	    const repo = this.manager.repoFor(this.target.repoRoot);
219	    if (!repo) {
220	      this.showError('The repository for this tab is not open in this window.', false);
221	      return;
222	    }
223	
224	    const entry =
225	      this.target.mode === 'session' && this.target.sessionId
226	        ? this.manager.sessionEntry(repo, this.target.sessionId)
227	        : undefined;
228	    let checkpointId =
229	      this.target.mode === 'checkpoint'
230	        ? this.target.checkpointId
231	        : (entry?.checkpoints[0]?.checkpointId ?? entry?.local?.lastCheckpointId);
232	    if (!checkpointId && entry?.listedCheckpoints) {
233	      // A session of another branch: the clone has none of its checkpoints, and Entire lists them.
234	      const listed = await this.manager.sessionCheckpoints(repo, entry.sessionId, { wait: true, signal });
235	      checkpointId = listed[0]?.checkpointId;
236	      if (stale()) return;
237	    }
238	
239	    if (!checkpointId) {
240	      this.loaded = this.sessionOnly(repo, entry);
241	      this.panel.title = shortTitle(this.loaded.header.title);
242	      this.sendLoaded();
243	      return;
244	    }
245	
246	    const detail = await this.manager.detail(repo, checkpointId, signal);
247	    if (stale()) return;
248	    if (!detail.ok) {
249	      if (detail.failure.kind === 'notFound') {
250	        // The checkpoint's data was never uploaded. The commit is still here, so show that.
251	        const commit = await this.findCommit(repo, checkpointId);
252	        const files = await this.files(repo, [], commit);
253	        if (stale()) return;
254	        this.loaded = this.withoutData(repo, checkpointId, commit, files, entry);
255	        this.panel.title = shortTitle(this.loaded.header.title);
256	        this.sendLoaded();
257	      } else if (detail.failure.kind !== 'aborted') {
258	        this.showError(detail.failure.message, true);
259	      }
260	      return;
261	    }
262	
263	    const sessions = detail.value.sessions;
264	    const position = this.selectPosition(detail.value);
265	    const slot = sessions[position];
266	
267	    const commit = await this.findCommit(repo, checkpointId);
268	    if (stale()) return;
269	    const touched = slot && slot.filesTouched.length > 0 ? slot.filesTouched : detail.value.filesTouched;
270	    const files = await this.files(repo, touched, commit);
271	    if (stale()) return;
272	
273	    const tree = await this.manager.store.locate(repo.root, checkpointId);
274	    const stored = tree && slot ? (await this.manager.store.sessions(repo.root, tree))[slot.index] : undefined;
275	    if (stale()) return;
276	    const transcript = await this.transcript(repo, checkpointId, tree, stored, position === sessions.length - 1, signal);
277	    if (stale()) return;
278	
279	    const headerSessions = sessions.map((session): HeaderSession => {
280	      const header: HeaderSession = { index: session.index };
281	      if (session.sessionId) header.sessionId = session.sessionId;
282	      if (session.agent) header.agent = session.agent;
283	      if (session.model) header.model = session.model;
284	      if (session.tokenUsage) header.tokens = totalTokens(session.tokenUsage);
285	      if (session.createdAt) header.createdAt = session.createdAt;
286	      if (session.summary?.intent) header.intent = session.summary.intent;
287	      if (session.summary?.outcome) header.outcome = session.summary.outcome;
288	      return header;
289	    });
290	
291	    const row = repo.index?.row(checkpointId);
292	    const sessionId = slot?.sessionId ?? (this.target.mode === 'session' ? this.target.sessionId : undefined);
293	    // The transcript opens with the prompt that names a session Entire has
294	    // not named. The Sessions view is told, so that its row has the name too.
295	    const opening = transcript.fromSessionStart ? openingPrompt(transcript.parsed.turns) : undefined;
296	    if (opening && slot?.sessionId) this.manager.noteSessionName(repo, slot.sessionId, opening);
297	    const title =
298	      (this.target.mode === 'session' ? headline(entry?.name ?? opening ?? entry?.lastPrompt, 120) : '') ||
299	      commit?.subject ||
300	      headline(row?.message, 120) ||
301	      checkpointId;
302	
303	    const header: PanelHeader = {
304	      mode: this.target.mode,
305	      title,
306	      checkpointId,
307	      otherCommits: Math.max(0, (repo.index?.commitsFor(checkpointId).length ?? 0) - 1),
308	      sessions: headerSessions,
309	      selected: position,
310	      files,
311	      canOpenOnWeb: repo.entireRepo !== undefined && (commit !== undefined || sessionId !== undefined),
312	      canShowCommitDiff: commit !== undefined,
313	      canOpenRaw: slot !== undefined,
314	    };
315	    if (commit) {
316	      header.commit = {
317	        sha: commit.sha,
318	        shortSha: commit.shortSha,
319	        subject: commit.subject,
320	        author: commit.author,
321	        date: new Date(commit.authorTime * 1000).toISOString(),
322	      };
323	    }
324	    if (detail.value.branch) header.branch = detail.value.branch;
325	    if (entry) header.localSession = localSession(entry);
326	    if (detail.value.partial) header.notice = 'The Entire CLI could read only part of this checkpoint.';
327	    // The transcript does not say who sent its prompts. The CLI takes that
328	    // to be the author of the commit that carries the checkpoint.
329	    const promptAuthor = commit?.author || repo.checkpointAuthors.get(checkpointId);
330	    if (promptAuthor) header.promptAuthor = promptAuthor;
331	
332	    // A panel on one checkpoint says where that checkpoint sits in its
333	    // session and can step to the ones around it. A panel on a session shows
334	    // the whole conversation, so it has no place to report.
335	    const place =
336	      this.target.mode === 'checkpoint' && slot?.sessionId
337	        ? repo.index?.position(slot.sessionId, checkpointId)
338	        : undefined;
339	    if (place) {
340	      header.position = {
341	        ordinal: place.ordinal,
342	        total: place.total,
343	        mayHaveEarlier: place.mayHaveEarlier,
344	        hasPrevious: place.previous !== undefined,
345	        hasNext: place.next !== undefined,
346	      };
347	    }
348	
349	    const wire = transcript.parsed.turns.map(toWireTurn);
350	    const info: TranscriptInfo = {
351	      source: transcript.source,
352	      total: wire.length,
353	      // A session view shows the whole conversation, not one checkpoint's part of it.
354	      start: this.target.mode === 'session' ? 0 : transcript.parsed.startTurn,
355	    };
356	    if (transcript.notice) info.notice = transcript.notice;
357	
358	    this.loaded = {
359	      repo,
360	      header,
361	      info,
362	      turns: transcript.parsed.turns,
363	      wire,
364	      detail: detail.value,
365	      checkpointId,
366	      ...(commit ? { commit } : {}),
367	      ...(slot ? { sessionIndex: slot.index } : {}),
368	      ...(sessionId ? { sessionId } : {}),
369	      ...(place ? { neighbors: { ...(place.previous ? { previous: place.previous } : {}), ...(place.next ? { next: place.next } : {}) } } : {}),
370	      ...(tree ? { tree } : {}),
371	      ...(stored ? { stored } : {}),
372	    };
373	    this.panel.title = shortTitle(title);
374	    this.sendLoaded();
375	    if (!promptAuthor && wire.length > 0) void this.findPromptAuthor(repo, checkpointId, this.loaded, signal);
376	  }
377	
378	  /**
379	   * Asks the CLI who the author of a checkpoint is, and puts the name on the
380	   * prompts already drawn. This is for a checkpoint that no commit in the
381	   * history read so far carries, such as one made on another branch. The
382	   * call takes a second or two, so the transcript does not wait for it.
383	   */
384	  private async findPromptAuthor(
385	    repo: RepoContext,
386	    checkpointId: string,
387	    loaded: Loaded,
388	    signal: AbortSignal,
389	  ): Promise<void> {
390	    const author = await this.manager.cli?.checkpointAuthor(repo.root, checkpointId, signal);
391	    if (!author?.ok || !author.value) return;
392	    repo.checkpointAuthors.set(checkpointId, author.value);
393	    if (this.loaded !== loaded || this.disposed) return;
394	    loaded.header.promptAuthor = author.value;
395	    this.post({ type: 'promptAuthor', name: author.value });
396	  }
397	
398	  /** A local session that no checkpoint references yet: facts only, no transcript view. */
399	  private sessionOnly(repo: RepoContext, entry: SessionEntry | undefined): Loaded {
400	    const sessionId = this.target.sessionId ?? '';
401	    const header: PanelHeader = {
402	      mode: 'session',
403	      title: headline(entry?.name ?? entry?.lastPrompt, 120) || `${entry?.agent ?? 'Agent'} session`,
404	      otherCommits: 0,
405	      sessions: [],
406	      selected: 0,
407	      files: [],
408	      canOpenOnWeb: repo.entireRepo !== undefined && sessionId !== '',
409	      canShowCommitDiff: false,
410	      canOpenRaw: entry?.local !== undefined,
411	    };
412	    if (entry) header.localSession = localSession(entry);
413	    return {
414	      repo,
415	      header,
416	      info: {
417	        source: 'none',
418	        total: 0,
419	        start: 0,
420	        notice: entry
421	          ? 'This session has no checkpoint yet. Its transcript appears here after a commit that includes its work.'
422	          : 'Entire has no record of this session in this repository.',
423	      },
424	      turns: [],
425	      wire: [],
426	      ...(sessionId ? { sessionId } : {}),
427	    };
428	  }
429	
430	  private selectPosition(detail: CheckpointDetail): number {
431	    const count = detail.sessions.length;
432	    if (count === 0) return 0;
433	    if (this.pickedPosition !== undefined && this.pickedPosition < count) return this.pickedPosition;
434	    if (this.target.sessionId) {
435	      const found = detail.sessions.findIndex((session) => session.sessionId === this.target.sessionId);
436	      if (found >= 0) return found;
437	    }
438	    // The latest session is the one the CLI itself shows by default.
439	    return count - 1;
440	  }
441	
442	  private async findCommit(repo: RepoContext, checkpointId: string): Promise<CommitRecord | undefined> {
443	    const carriers = repo.index?.commitsFor(checkpointId) ?? [];
444	    const wanted = this.target.commitSha;
445	    if (wanted) {
446	      return carriers.find((commit) => commit.sha === wanted) ?? (await this.manager.git.commit(repo.root, wanted));
447	    }
448	    return carriers[0];
449	  }
450	
451	  /**
452	   * A checkpoint that a commit names but whose session data the CLI cannot
453	   * find. The panel shows what git knows about the commit and says why there
454	   * is no transcript.
455	   */
456	  private withoutData(
457	    repo: RepoContext,
458	    checkpointId: string,
459	    commit: CommitRecord | undefined,
460	    files: HeaderFile[],
461	    /** The session the tab was opened for, when it was opened for a session and not for the checkpoint. */
462	    session?: SessionEntry,
463	  ): Loaded {
464	    const hosted = repo.entireRepo !== undefined;
465	    const header: PanelHeader = {
466	      mode: session ? 'session' : 'checkpoint',
467	      title: (session ? headline(session.name ?? session.lastPrompt, 120) : '') || commit?.subject || checkpointId,
468	      checkpointId,
469	      otherCommits: Math.max(0, (repo.index?.commitsFor(checkpointId).length ?? 0) - 1),
470	      sessions: [],
471	      selected: 0,
472	      files,
473	      // A session has a page on entire.com whether or not a commit here carries its checkpoint.
474	      canOpenOnWeb: hosted && (commit !== undefined || session !== undefined),
475	      canShowCommitDiff: commit !== undefined,
476	      canOpenRaw: false,
477	    };
478	    if (commit) {
479	      header.commit = {
480	        sha: commit.sha,
481	        shortSha: commit.shortSha,
482	        subject: commit.subject,
483	        author: commit.author,
484	        date: new Date(commit.authorTime * 1000).toISOString(),
485	      };
486	    }
487	    return {
488	      repo,
489	      header,
490	      info: {
491	        source: 'none',
492	        total: 0,
493	        start: 0,
494	        notice:
495	          session && hosted && session.listedCheckpoints !== undefined
496	            ? // Entire lists the session, so its data is there, even though the CLI did not find it.
497	              "The Entire CLI could not find the session data of this session's latest checkpoint, on this machine or on the remote. Entire lists the session, so its page on entire.com may have the transcript."
498	            : "Entire has no session data for this checkpoint. The commit records the checkpoint's ID, but the session data is uploaded separately, and this checkpoint's is not on this machine or on the remote. If its author still has it, running \"entire checkpoint push\" on their machine uploads it.",
499	      },
500	      turns: [],
501	      wire: [],
502	      checkpointId,
503	      ...(commit ? { commit } : {}),
504	      ...(session ? { sessionId: session.sessionId } : {}),
505	    };
506	  }
507	
508	  /** Files the session touched, marked with a status when the commit changed them. */
509	  private async files(repo: RepoContext, touched: string[], commit: CommitRecord | undefined): Promise<HeaderFile[]> {
510	    const changes = commit ? await this.manager.git.commitFiles(repo.root, commit.sha) : [];
511	    const status = new Map(changes.map((change) => [change.path, change.status]));
512	    const paths = touched.length > 0 ? touched : changes.map((change) => change.path);
513	    return paths.map((filePath): HeaderFile => {
514	      // Agents record absolute paths at times. Show them relative to the repository.
515	      const relative = path.isAbsolute(filePath) ? path.relative(repo.root, filePath) : filePath;
516	      const letter = status.get(relative);
517	      return letter ? { path: relative, status: letter } : { path: relative };
518	    });
519	  }
520	
521	  private async transcript(
522	    repo: RepoContext,
523	    checkpointId: string,
524	    tree: CheckpointTree | undefined,
525	    stored: StoredSession | undefined,
526	    isLatestSession: boolean,
527	    signal: AbortSignal,
528	  ): Promise<{
529	    parsed: ParsedTranscript;
530	    source: TranscriptInfo['source'];
531	    /** The transcript holds the session from its start, so its first prompt is the one that opened the session. */
532	    fromSessionStart: boolean;
533	    notice?: string;
534	  }> {
535	    if (tree && stored) {
536	      const text = await this.manager.store.compactTranscript(repo.root, tree, stored, signal);
537	      if (text !== undefined) {
538	        const meta = await this.manager.store.sessionMeta(repo.root, tree, stored);
539	        return {
540	          parsed: parseCompactTranscript(text, meta?.compactTranscriptStart),
541	          source: 'compact',
542	          // Without a start line, the file holds only this checkpoint's part of the session.
543	          fromSessionStart: typeof meta?.compactTranscriptStart === 'number',
544	        };
545	      }
546	    }
547	    // The CLI's text view covers only the latest session of a checkpoint.
548	    if (isLatestSession && this.manager.cli) {
549	      const text = await this.manager.cli.fullText(repo.root, checkpointId, signal);
550	      if (text.ok) {
551	        return {
552	          parsed: parseCliText(text.value),
553	          source: 'cliText',
554	          // The CLI's text view is of the whole session.
555	          fromSessionStart: true,
556	          notice:
557	            'Text view from the Entire CLI. This session has no normalized transcript, so tool inputs and results are not shown.',
558	        };
559	      }
560	    }
561	    return {
562	      parsed: { turns: [], startTurn: 0 },
563	      source: 'none',
564	      fromSessionStart: false,
565	      notice: 'No transcript preview is available for this session. Open the raw transcript to read it.',
566	    };
567	  }
568	
569	  private async onMessage(raw: unknown): Promise<void> {
570	    if (!isWebviewMessage(raw)) return;
571	    const message: WebviewMessage = raw;
572	    if (message.type === 'ready') {
573	      this.ready = true;
574	      if (this.loaded) this.sendLoaded();
575	      else if (this.error) this.post({ type: 'error', ...this.error });
576	      else this.post({ type: 'loading', title: 'Loading' });
577	      return;
578	    }
579	    if (message.type === 'retry') {
580	      void this.load();
581	      return;
582	    }
583	    if (message.type === 'openLink') {
584	      await this.actions.openExternal(message.href);
585	      return;
586	    }
587	
588	    const loaded = this.loaded;
589	    if (!loaded) return;
590	    const { repo } = loaded;
591	
592	    switch (message.type) {
593	      case 'selectSession':
594	        this.selectSession(message.position);
595	        return;
596	      case 'stepSession':
597	        this.step(message.direction);
598	        return;
599	      case 'requestToolBody': {
600	        const block = loaded.turns[message.turn]?.blocks[message.block];
601	        if (block?.kind !== 'tool') return;
602	        const input = toolInputText(block.input);
603	        const output = block.output ?? '';
604	        this.post({
605	          type: 'toolBody',
606	          requestId: message.requestId,
607	          input: input.slice(0, BODY_LIMIT),
608	          output: output.slice(0, BODY_LIMIT),
609	          truncated: input.length > BODY_LIMIT || output.length > BODY_LIMIT,
610	        });
611	        return;
612	      }
613	      case 'openToolBody': {
614	        const block = loaded.turns[message.turn]?.blocks[message.block];
615	        if (block?.kind !== 'tool') return;
616	        const parts = [`# ${block.name}`, '', '## Input', '', toolInputText(block.input), '', '## Result', '', block.output ?? ''];
617	        await this.actions.openText(block.name, parts.join('\n'));
618	        return;
619	      }
620	      case 'requestImage':
621	        this.post(await this.image(loaded, message.requestId, message.turn, message.block));
622	        return;
623	      case 'openOnWeb':
624	        if (loaded.commit && loaded.header.mode === 'checkpoint') {
625	          await this.actions.openCommitOnWeb(repo, loaded.commit.sha);
626	        } else if (loaded.sessionId) {
627	          await this.actions.openSessionOnWeb(repo, loaded.sessionId);
628	        } else if (loaded.commit) {
629	          await this.actions.openCommitOnWeb(repo, loaded.commit.sha);
630	        }
631	        return;
632	      case 'showCommitDiff':
633	        if (loaded.commit) await this.actions.showCommitDiff(repo, loaded.commit.sha);
634	        return;
635	      case 'openFile': {
636	        const file = loaded.header.files[message.index];
637	        if (file) await this.actions.openFile(repo, loaded.commit?.sha, file.path);
638	        return;
639	      }
640	      case 'openRawTranscript':
641	        if (loaded.checkpointId && loaded.sessionIndex !== undefined) {
642	          await this.actions.openRawCheckpointTranscript(repo, loaded.checkpointId, loaded.sessionIndex);
643	        } else if (loaded.sessionId) {
644	          await this.actions.openRawSessionTranscript(repo, loaded.sessionId);
645	        }
646	        return;
647	      case 'copy': {
648	        const value =
649	          message.target === 'checkpointId'
650	            ? loaded.checkpointId
651	            : message.target === 'commitSha'
652	              ? loaded.commit?.sha
653	              : loaded.sessionId;
654	        const label =
655	          message.target === 'checkpointId' ? 'checkpoint ID' : message.target === 'commitSha' ? 'commit SHA' : 'session ID';
656	        if (value) await this.actions.copy(value, label);
657	        return;
658	      }
659	    }
660	  }
661	
662	  private async image(loaded: Loaded, requestId: number, turn: number, blockIndex: number): Promise<HostMessage> {
663	    const unavailable: HostMessage = { type: 'imageUnavailable', requestId };
664	    const block = loaded.turns[turn]?.blocks[blockIndex];
665	    if (block?.kind !== 'image') return unavailable;
666	
667	    let base64 = block.base64;
668	    let mediaType = block.mediaType;
669	    if (!base64 && block.assetPath && loaded.tree && loaded.stored) {
670	      const data = await this.manager.store.asset(loaded.repo.root, loaded.tree, loaded.stored, block.assetPath);
671	      base64 = data?.toString('base64');
672	      mediaType ??= IMAGE_TYPES[path.extname(block.assetPath).slice(1).toLowerCase()];
673	    }
674	    // SVG is left out on purpose: it is the one image type that can carry script.
675	    if (!base64 || base64.length > IMAGE_LIMIT || !mediaType || !Object.values(IMAGE_TYPES).includes(mediaType)) {
676	      return unavailable;
677	    }
678	    return { type: 'image', requestId, mediaType, base64 };
679	  }
680	}
681	
682	function localSession(entry: SessionEntry): HeaderLocalSession {
683	  const local: HeaderLocalSession = { sessionId: entry.sessionId };
684	  if (entry.status) local.status = entry.status;
685	  if (entry.agent) local.agent = entry.agent;
686	  if (entry.model) local.model = entry.model;
687	  if (entry.local?.turns !== undefined) local.turns = entry.local.turns;
688	  if (entry.local?.pendingTurns !== undefined) local.pendingTurns = entry.local.pendingTurns;
689	  if (entry.local?.tokens) local.tokens = entry.local.tokens.total;
690	  if (entry.local?.startedAt) local.startedAt = entry.local.startedAt;
691	  if (entry.lastActive) local.lastActive = entry.lastActive;
692	  return local;
693	}
694	
695	function shortTitle(title: string): string {
696	  return title.length > 40 ? `${title.slice(0, 39)}…` : title;
697	}
