100	  if (section.state !== 'ready') return `<section>${heading}${notice(section)}</section>`;
101	
102	  const actions =
103	    button('View Brain', 'entire.openBrainGraph', [section.root], 'primary') +
104	    (section.running ? button('Stop', 'entire.stopBrainGraph', [section.root]) : '');
105	  const running = section.running
106	    ? `<p class="muted">The graph is running on ${escapeHtml(section.running)}.</p>`
107	    : '';
108	  // The details are text, not rows of a list: nothing about them can be clicked, so nothing looks as if it could.
109	  const rows = section.details
110	    .map((detail) => {
111	      // The row itself has no box to hover: its two cells lie in the grid of the list.
112	      const title = detail.tooltip ? ` title="${escapeHtml(detail.tooltip)}"` : '';
113	      return `<div class="row${detail.attention ? ' attention' : ''}"><dt${title}>${escapeHtml(detail.label)}</dt><dd${title}>${escapeHtml(detail.value)}</dd></div>`;
114	    })
115	    .join('');
116	  return `<section>${heading}<p class="actions">${actions}</p>${running}<dl>${rows}</dl></section>`;
117	}
