131	      : sections.map((section) => sectionHtml(section, sections.length > 1)).join('');
132	  return `<!DOCTYPE html>
133	<html lang="en">
134	<head>
135	<meta charset="UTF-8">
136	<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'nonce-${escapeHtml(nonce)}'">
137	<meta name="viewport" content="width=device-width, initial-scale=1.0">
138	<style nonce="${escapeHtml(nonce)}">${STYLES}</style>
139	<title>Brain</title>
140	</head>
141	<body>${body}</body>
142	</html>`;
