282	      if (node.kind === 'trail') return actions.copyTrailLink(node.repo, node.trail.number);
283	      return undefined;
284	    }),
285	
286	    onNode('entire.copySessionId', (node) => {
287	      const { sessionId } = nodeFacts(node);
288	      if (sessionId) return actions.copy(sessionId, 'session ID');
289	      return undefined;
290	    }),
291	  ];
292	}
