 * The plugin binds to the loopback address only. The address returned here is
 * rebuilt from the port number, so whatever else the line holds, the
 * extension opens a page on this machine and nothing else.
 */
export function parseVizUrl(line: string): string | undefined {
  const port = Number(VIZ_ADDRESS.exec(line)?.[1]);
  return Number.isInteger(port) && port >= 1 && port <= 65535 ? `http://127.0.0.1:${port}` : undefined;
}

/**
 * Whether the CLI's complaint means the entire-brain plugin is not installed.
 * Without the plugin, `brain` is not a command the CLI knows: it prints
 * `unknown command "brain …"`, and newer versions name the plugin and how to
 * install it.
 */
export function isPluginMissing(output: string): boolean {
  return /unknown command "brain\b|entire-brain plugin is not installed|entire plugin install brain/i.test(output);
}

